func (p *UserPatch) clearEdge(edge string) error {
	switch edge {

	case user.EdgeCard:

		if p.clearedEdges == nil {
			p.clearedEdges = make(map[string]bool)
		}
		p.clearedEdges[edge] = true
		p.CardID = ent.Null[int]()
		return nil

	case user.EdgePets:
		p.Pets.Clear = true
		return nil

	case user.EdgeFiles:
		p.Files.Clear = true
		return nil

	case user.EdgeGroups:
		p.Groups.Clear = true
		return nil

	case user.EdgeFriends:
		p.Friends.Clear = true
		return nil

	case user.EdgeFollowers:
		p.Followers.Clear = true
		return nil

	case user.EdgeFollowing:
		p.Following.Clear = true
		return nil

	case user.EdgeTeam:

		if p.clearedEdges == nil {
			p.clearedEdges = make(map[string]bool)
		}
		p.clearedEdges[edge] = true
		p.TeamID = ent.Null[int]()
		return nil

	case user.EdgeSpouse:

		if p.clearedEdges == nil {
			p.clearedEdges = make(map[string]bool)
		}
		p.clearedEdges[edge] = true
		p.SpouseID = ent.Null[int]()
		return nil

	case user.EdgeChildren:
		p.Children.Clear = true
		return nil

	case user.EdgeParent:

		if p.clearedEdges == nil {
			p.clearedEdges = make(map[string]bool)
		}
		p.clearedEdges[edge] = true
		p.ParentID = ent.Null[int]()
		return nil

	}
	return &ValidationError{Name: edge, err: fmt.Errorf("ent: edge %q of User cannot be cleared", edge)}
}

func (p *UserPatch) apply(other UserPatch) {

	if other.OptionalInt.IsSet() {
		p.OptionalInt = other.OptionalInt
		delete(p.expressions, user.FieldOptionalInt)
	}

	if value, ok := other.OptionalIntAdd.Get(); ok {
		if current, exists := p.OptionalIntAdd.Get(); exists {
			value += current
		}
		p.OptionalIntAdd = ent.Some(value)
	}

	if other.Tags.IsSet() {
		p.Tags = other.Tags
		delete(p.expressions, user.FieldTags)
	}

	if other.Scores.IsSet() {
		p.Scores = other.Scores
		delete(p.expressions, user.FieldScores)
	}

	if other.Age.IsSet() {
		p.Age = other.Age
		delete(p.expressions, user.FieldAge)
	}

	if value, ok := other.AgeAdd.Get(); ok {
		if current, exists := p.AgeAdd.Get(); exists {
			value += current
		}
		p.AgeAdd = ent.Some(value)
	}

	if other.Name.IsSet() {
		p.Name = other.Name
		delete(p.expressions, user.FieldName)
	}

	if other.Last.IsSet() {
		p.Last = other.Last
		delete(p.expressions, user.FieldLast)
	}

	if other.Nickname.IsSet() {
		p.Nickname = other.Nickname
		delete(p.expressions, user.FieldNickname)
	}

	if other.Address.IsSet() {
		p.Address = other.Address
		delete(p.expressions, user.FieldAddress)
	}

	if other.Phone.IsSet() {
		p.Phone = other.Phone
		delete(p.expressions, user.FieldPhone)
	}

	if other.Password.IsSet() {
		p.Password = other.Password
		delete(p.expressions, user.FieldPassword)
	}

	if other.Role.IsSet() {
		p.Role = other.Role
		delete(p.expressions, user.FieldRole)
	}

	if other.Employment.IsSet() {
		p.Employment = other.Employment
		delete(p.expressions, user.FieldEmployment)
	}

	if other.SSOCert.IsSet() {
		p.SSOCert = other.SSOCert
		delete(p.expressions, user.FieldSSOCert)
	}

	if other.FilesCount.IsSet() {
		p.FilesCount = other.FilesCount
		delete(p.expressions, user.FieldFilesCount)
	}

	if value, ok := other.FilesCountAdd.Get(); ok {
		if current, exists := p.FilesCountAdd.Get(); exists {
			value += current
		}
		p.FilesCountAdd = ent.Some(value)
	}

	if other.CardID.IsSet() {
		p.CardID = other.CardID
	}

	p.Pets.Add = append(p.Pets.Add, other.Pets.Add...)
	p.Pets.Remove = append(p.Pets.Remove, other.Pets.Remove...)
	p.Pets.Clear = p.Pets.Clear || other.Pets.Clear

	p.Files.Add = append(p.Files.Add, other.Files.Add...)
	p.Files.Remove = append(p.Files.Remove, other.Files.Remove...)
	p.Files.Clear = p.Files.Clear || other.Files.Clear

	p.Groups.Add = append(p.Groups.Add, other.Groups.Add...)
	p.Groups.Remove = append(p.Groups.Remove, other.Groups.Remove...)
	p.Groups.Clear = p.Groups.Clear || other.Groups.Clear

	p.Friends.Add = append(p.Friends.Add, other.Friends.Add...)
	p.Friends.Remove = append(p.Friends.Remove, other.Friends.Remove...)
	p.Friends.Clear = p.Friends.Clear || other.Friends.Clear

	p.Followers.Add = append(p.Followers.Add, other.Followers.Add...)
	p.Followers.Remove = append(p.Followers.Remove, other.Followers.Remove...)
	p.Followers.Clear = p.Followers.Clear || other.Followers.Clear

	p.Following.Add = append(p.Following.Add, other.Following.Add...)
	p.Following.Remove = append(p.Following.Remove, other.Following.Remove...)
	p.Following.Clear = p.Following.Clear || other.Following.Clear

	if other.TeamID.IsSet() {
		p.TeamID = other.TeamID
	}
	if other.SpouseID.IsSet() {
		p.SpouseID = other.SpouseID
	}

	p.Children.Add = append(p.Children.Add, other.Children.Add...)
	p.Children.Remove = append(p.Children.Remove, other.Children.Remove...)
	p.Children.Clear = p.Children.Clear || other.Children.Clear

	if other.ParentID.IsSet() {
		p.ParentID = other.ParentID
	}
	for column, render := range other.expressions {
		p.setExpr(column, render)
	}
	for edge, clear := range other.clearedEdges {
		if clear {
			if p.clearedEdges == nil {
				p.clearedEdges = make(map[string]bool)
			}
			p.clearedEdges[edge] = true
		}
	}
}
